<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>My loans | Digital Library</title><link rel="stylesheet" href="/assets/app.css"></head><body><header class="site-header"><a class="brand" href="/dashboard">Digital Library</a><nav><a href="/">Catalog</a></nav></header><main class="container"><p class="eyebrow">Member account</p><h1>My loans</h1><?php if ($error): ?><p class="form-error" role="alert"><?= e($error) ?></p><?php endif; ?><?php if ($success): ?><p class="form-success" role="status"><?= e($success) ?></p><?php endif; ?><?php if ($loans === []): ?><div class="empty-state"><h2>No active loans</h2></div><?php else: ?><div class="book-grid"><?php foreach ($loans as $loan): ?><article class="book-card"><h2><?= e($loan['title']) ?></h2><p>Copy <?= e($loan['accession_number']) ?></p><p class="muted">Due <?= e($loan['due_at']) ?></p></article><?php endforeach; ?></div><?php endif; ?></main></body></html>